// Titles, captions and explanations for every machine, and the order they appear in.
const LAW1 = ['First law of thermodynamics', 'Suspended', 'In force'], LAW2 = ['Second law of thermodynamics', 'Suspended', 'In force'];
const ALL = [

    { k: 1, m: 'wheel', title: 'The overbalanced wheel', cap: 'Overbalanced wheel, after Bhāskara II, c. 1150', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Speed', 'Balls on right', 'Balls on left'], stamp: 'Makes work from nothing',
      aria: 'A wheel with twelve curved spokes. A ball rolls along each spoke, far from the axle on the right and close to it on the left.',
      claim: 'Balls roll along curved spokes. On the right they sit out near the rim, on the left they huddle by the axle. A weight far from the axle has more leverage, so the right side should always win and the wheel should turn itself, with power to spare. Bhāskara II described a wheel like this around 1150, and new versions kept appearing for seven centuries.',
      why: 'Count the balls. The curve that throws a ball outward also carries it past the bottom and onto the left, so fewer balls are on the right than on the left. A few weights on long arms balance many weights on short arms. Over a full turn every ball comes back to the height it started from, which means gravity has done no work in total. Friction then takes what motion there was.' },
    { k: 1, m: 'windmill', title: 'The self-blowing windmill', cap: 'Windmill and bellows, after Zimara, 1518', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Sails', 'Pumping costs', 'Gust gives back'], stamp: 'Gust returns less than it costs',
      aria: 'A windmill linked by a belt and crank to a pair of bellows. The bellows blow puffs of air at the sails.',
      claim: 'A windmill works a pair of bellows, and the bellows blow on the windmill. Mark Antony Zimara proposed it in 1518 and left out any detail of how to build it. Once started by hand, the wind the mill makes for itself should keep it turning.',
      why: 'Squeezing the bellows takes work, and the gust that comes out carries at most that much. Most of the gust misses the sails, swirls away and ends as slightly warmer air. The sails get back a fraction of what the bellows cost, so every turn is weaker than the one before.' },
    { k: 1, m: 'stevin', title: 'The wreath of spheres', cap: 'Chain on a wedge, after Simon Stevin, 1586', tag: 'First kind · work from nothing', law: LAW1,
      read: ['On the long side', 'On the short side', 'Chain speed'], stamp: 'Both sides pull alike',
      aria: 'A loop of eighteen beads draped over a triangular wedge with one long gentle side and one short steep side.',
      claim: 'A loop of beads lies over a wedge. More beads rest on the long side than on the short side, so the long side should be heavier and drag the whole loop round for ever.',
      why: 'The long side holds more beads, but it is gentler, so each bead pulls along it less. The number of beads times the steepness comes out the same on both sides. Stevin drew this figure to show that the chain must stay put, and from that he worked out the law of the inclined plane. He was pleased enough to put it on his title page.' },
    { k: 1, m: 'fludd', title: 'The water screw mill', cap: 'Closed-cycle mill, after Robert Fludd, 1618', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Wheel', 'Falls on the wheel', 'Screw lifts back'], stamp: 'Lifts less than falls',
      aria: 'Water falls from a trough onto a water wheel. The wheel drives an Archimedes screw that lifts water from a basin back to the trough.',
      claim: 'Water falls from a trough onto a wheel. The wheel turns an Archimedes screw, and the screw lifts the water back up to the trough. With the loop closed, the mill should run for ever on the same few buckets. Robert Fludd published a drawing of one in 1618.',
      why: 'Water falling one metre can at best lift the same water one metre, and only if nothing is lost. The wheel spills, the screw leaks and the gearing rubs, so less water goes up than came down. The trough runs dry and everything ends in the lower basin.' },
    { k: 1, m: 'wilkins', title: 'The magnet and the ramp', cap: 'Lodestone and ramp, described by John Wilkins, 1648', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Laps', 'Ball', 'Height'], stamp: 'Ball sticks to the magnet',
      aria: 'An iron ball climbs a straight ramp toward a magnet on a post, drops through a hole near the top and rolls back down a curved ramp.',
      claim: 'A lodestone on a post draws an iron ball up a ramp. Just before the top the ball meets a hole, drops through, and rolls down a second ramp to the start, where the magnet catches it again. John Wilkins described the scheme in 1648, and doubted it.',
      why: 'A magnet strong enough to haul the ball up the ramp is strong enough to carry it across the hole, so the ball ends up stuck to the lodestone. If the ball did fall, the magnet would pull against it all the way down and take back exactly what it gave on the way up.' },
    { k: 1, m: 'boyle', title: 'The self-filling flask', cap: 'Self-filling flask, attributed to Robert Boyle', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Bowl level', 'Tube level', 'Flow'], stamp: 'Levels stay equal',
      aria: 'A wide bowl of water whose stem runs down, round and up into a thin tube that bends over to pour back into the bowl.',
      claim: 'A wide bowl drains through its stem into a thin tube that bends up and over the rim. The bowl holds far more water than the tube, so its weight should push the thin column up, over the top and back into the bowl in an endless stream.',
      why: 'Pressure in a liquid depends on depth and not on how much liquid there is. A thimbleful in the tube balances the whole bowl once it stands at the same height. The water in the tube rises to the level of the bowl and stops there, well short of the spout.' },
    { k: 1, m: 'congreve', title: 'The sponge band', cap: 'Capillary engine, after Sir William Congreve, 1827', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Band speed', 'Wet side pulls', 'Leaving water costs'], stamp: 'Sponge keeps its water',
      aria: 'An endless band of sponge on three rollers with its lower run under water. One side stands upright and one side slopes.',
      claim: 'An endless band of sponge runs round three rollers, with its lower run under water. On the upright side the sponge soaks up water by capillary action and grows heavy. On the sloping side a chain of weights squeezes it dry. The wet side should sink for ever.',
      why: 'The pull that draws water up into the sponge also holds it there. Lifting the wet band clear of the water, and then wringing it, costs at least as much work as the extra weight delivers on the way down. Capillary action can raise water, but it will not let go of it for free.' },
    { k: 1, m: 'floats', title: 'The float belt', cap: 'Float belt in a water column', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Belt speed', 'Gained on the climb', 'Paid at the seal'], stamp: 'Seal costs what the climb pays',
      aria: 'A belt of hollow floats on two pulleys. One side of the belt rises through a tall tank of water, entering through a seal in the bottom.',
      claim: 'A belt of hollow floats runs up through a tall column of water, entering by a watertight seal in the bottom. In the water each float is pushed upward. In the air on the other side nothing pushes back, so the belt should run for ever.',
      why: 'To get in at the bottom, a float has to push aside water at the full pressure of the column. That costs the pressure times the volume of the float, which is exactly what buoyancy pays back over the climb. The belt sticks at the seal.' },
    { k: 1, m: 'drum', title: 'The drum in the tank wall', cap: 'Drum half in water, half in air', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Drum speed', 'Lift on the axle', 'Twist on the drum'], stamp: 'Pressure aims at the axle',
      aria: 'A drum set in a slot in the wall of a water tank, with its right half under water and its left half in the air.',
      claim: 'A drum is mounted in a slot in the side of a tank, so that half of it is under water and half is in the air. Water buoys things up, so the wet half should keep rising and the drum should spin.',
      why: 'Water presses on a surface at right angles to it. On a round drum every one of those pushes points straight at the axle, so none of them turns it. The water lifts the axle hard and twists the drum not at all.' },
    { k: 1, m: 'motor', title: 'The motor and the dynamo', cap: 'Motor and dynamo in a ring', tag: 'First kind · work from nothing', law: LAW1,
      read: ['Motor draws', 'Dynamo gives', 'Lamp gets'], stamp: 'Losses on every lap',
      aria: 'An electric motor and a dynamo on a bench, joined by a belt. Wires run from the dynamo through a lamp and back to the motor.',
      claim: 'An electric motor turns a dynamo by a belt. The current from the dynamo runs the motor, with some to spare for a lamp. Start it with a push and it should feed itself.',
      why: 'Each machine turns a little of what it receives into heat in its windings and bearings. A good motor and a good dynamo each pass on about nine tenths, so one trip round the ring returns about four fifths of what set out. A few trips later nothing is left, with or without the lamp.' },
    { k: 1, m: 'cart', title: 'The magnet on a stick', cap: 'Self-pulling cart', tag: 'First kind · work from nothing', law: ["Newton's third law", 'Suspended', 'In force'],
      read: ['Speed', 'Magnet pulls cart', 'Cart pulls magnet'], stamp: 'Pulls cancel in the arm',
      aria: 'An iron cart with an arm that holds a horseshoe magnet just ahead of its front plate.',
      claim: 'Fix a strong magnet to an arm in front of an iron cart. The magnet pulls the cart forward. The cart carries the magnet along with it, so the pull never ends and the cart should gather speed without limit.',
      why: 'The cart pulls back on the magnet exactly as hard as the magnet pulls on the cart. The two pulls meet in the arm and cancel. It is the same reason you cannot lift yourself off the floor by your own belt.' },

    { k: 2, m: 'demon', title: "Maxwell's demon", cap: 'Sorting demon, after James Clerk Maxwell, 1867', tag: 'Second kind · work from heat at one temperature', law: LAW2,
      read: ['Left side', 'Right side', 'Door'], stamp: 'Memory has a price',
      aria: 'A box of gas molecules divided by a wall with a door. A small demon sits on the wall and works the door.',
      claim: 'A wall with a small door divides a box of gas. A tiny being watches the molecules and opens the door only for fast ones heading right and slow ones heading left. Without doing any work it makes one side hot and the other cold, and a difference in temperature can drive an engine. Maxwell invented the demon in 1867 to test the second law.',
      why: 'To sort molecules the demon has to observe them and remember what it saw. Its memory fills up, and wiping it clean gives off at least as much heat as the sorting saved. Rolf Landauer and Charles Bennett settled that account about a century later. A demon that cannot pay leaves the door open, and the two sides even out.' },
    { k: 2, m: 'zero', title: 'The zeromotor', cap: 'Ammonia engine, after John Gamgee, 1881', tag: 'Second kind · work from heat at one temperature', law: LAW2,
      read: ['Boiler pressure', 'Exhaust pressure', 'Flywheel'], stamp: 'Nothing cold to condense on',
      aria: 'A boiler of liquid ammonia feeds vapour to a piston and flywheel. The exhaust passes through a condenser coil and back to the boiler.',
      claim: 'Liquid ammonia boils far below the freezing point of water, so sea water is hot enough to raise ammonia vapour at more than four atmospheres. The vapour drives a piston. Gamgee held that it would cool as it expanded, turn back to liquid by itself, and be pumped round again. The United States Navy took an interest, since a ship driven this way would need no coal.',
      why: 'Vapour turns back to liquid only if it can hand its heat to something colder, and nothing on board is colder than the ammonia. The exhaust stays vapour, its pressure climbs until it matches the boiler, and the piston ends with the same push on both faces.' },
    { k: 2, m: 'ship', title: 'The sea-heat steamer', cap: 'Ship driven by the heat of the sea', tag: 'Second kind · work from heat at one temperature', law: LAW2,
      read: ['Speed', 'Heat taken from sea', 'Ice blocks dropped'], stamp: 'No colder place for the heat',
      aria: 'A steamship with no smoke crossing the sea and leaving a trail of ice blocks behind it.',
      claim: 'The sea holds an enormous store of heat. A ship could take in sea water, draw heat out of it to turn the propeller, and drop the water over the stern as ice. It burns no fuel and it makes no energy from nothing. Wilhelm Ostwald gave machines like this their name, the perpetual motion of the second kind.',
      why: 'Heat does work only on its way from somewhere hot to somewhere colder. A ship with nothing but the sea around it has no colder place to send the heat, and making ice takes work instead of giving it. Real ocean thermal plants do run, by using cold water pumped up from the deep.' },
    { k: 2, m: 'ratchet', title: 'The Brownian ratchet', cap: 'Ratchet and pawl, after Smoluchowski, 1912', tag: 'Second kind · work from heat at one temperature', law: LAW2,
      read: ['Teeth forward', 'Teeth back', 'Weights raised'], stamp: 'Takes work from even heat',
      aria: 'A paddle wheel in a box of gas molecules, linked by a belt to a ratchet wheel with a pawl. A cord from the ratchet lifts a small weight.',
      claim: 'Gas molecules strike a small paddle at random, nudging it one way and then the other. The paddle is coupled to a ratchet, and the pawl lets the ratchet turn in one direction only. Random nudges become steady rotation that winds up a weight. Marian Smoluchowski posed the device in 1912 and Richard Feynman made it famous in his lectures fifty years later.',
      why: 'For single molecules to move the paddle, the ratchet and pawl must be just as small. That makes them just as warm, so they jitter too. The pawl bounces off the teeth as often as it catches, and each bounce lets the wheel slip back. With everything at one temperature, forward and backward steps come out even and the weight sinks to the floor. The ratchet only turns when the pawl is kept colder than the gas, and then it is an ordinary heat engine.' },
    { k: 2, m: 'diode', title: 'The noise rectifier', cap: 'Resistor and diode, after Léon Brillouin, 1950', tag: 'Second kind · work from heat at one temperature', law: LAW2,
      read: ['Passed forward', 'Leaked back', 'On the capacitor'], stamp: 'Diode leaks as it passes',
      aria: 'A loop of wire with a resistor, a diode and a capacitor. A trace in the middle shows the current in the loop.',
      claim: 'The electrons in any warm resistor jostle about, giving a tiny random voltage that swings both ways. A diode passes current one way only. Put the two in a loop and the diode should pass the forward swings, block the rest, and slowly charge a capacitor from heat alone.',
      why: 'The diode is warm too. Its own electrons jostle just as hard and now and then jump the barrier backwards. At a single temperature the backward trickle matches the forward one exactly, and the capacitor stays empty. Cool the diode below the resistor and charge does flow, as in any heat engine.' },

    { k: 3, m: 'pend', title: 'The frictionless pendulum', cap: 'Pendulum under an evacuated bell jar', tag: 'Third kind · loses nothing, so never stops', law: ['Friction and drag', 'Removed', 'Present'],
      read: ['Swings', 'Amplitude', 'Energy left'], stamp: 'Cannot shed all friction',
      aria: 'A pendulum swinging inside a glass bell jar, above a scale marked in degrees.',
      claim: 'Hang a pendulum on a perfect pivot, pump every molecule of air out of the jar, and let go. With nothing to carry energy away, each swing rises as high as the last, for ever.',
      why: 'No pump removes every molecule and no pivot is perfect. Leftover gas drags on the bob, the pivot rubs, the rod flexes and warms. Each swing ends a little lower than the one before. Careful engineering stretches the run from minutes to days. Even then, drawing any work from the motion slows it down, so a machine of this kind can never be an engine.' },
    { k: 3, m: 'cradle', title: "Newton's cradle", cap: 'Cradle of perfectly elastic balls', tag: 'Third kind · loses nothing, so never stops', law: ['Losses at each collision', 'Removed', 'Present'],
      read: ['Clicks', 'Swing height', 'Lost at each click'], stamp: 'Every click costs',
      aria: 'Five balls hanging in a row from a frame. The end balls swing out in turn.',
      claim: 'Lift one ball and let go. It strikes the row, and the ball at the far end flies out to the same height. If the steel were perfectly springy and the air were absent, the clicks would go on for ever.',
      why: 'Each click you can hear is energy leaving as sound. The balls also warm a little where they strike, and the air drags on them. The swings shrink click by click until the row hangs still.' },
    { k: 3, m: 'fly', title: 'The flywheel in a vacuum', cap: 'Flywheel on magnetic bearings', tag: 'Third kind · loses nothing, so never stops', law: ['Gas drag and eddy currents', 'Removed', 'Present'],
      read: ['Speed', 'Energy stored', 'Drag'], stamp: 'Some drag always remains',
      aria: 'A heavy flywheel spinning inside a sealed round housing, with a ring of magnets around its shaft.',
      claim: 'Spin a heavy wheel inside a sealed housing with the air pumped out. Hold its shaft on magnets so that nothing touches it. With no air and no contact, nothing is left to slow it.',
      why: 'Some gas always remains and drags on the rim. The magnets that hold the shaft stir up small electric currents in the metal nearby, and those turn motion into heat. Flywheels like this are built to store energy and they do coast for hours, but they have to be topped up.' },
    { k: 3, m: 'ring', title: 'The superconducting ring', cap: 'Persistent current in a ring of lead', tag: 'Third kind · loses nothing, so never stops', law: ['Electrical resistance', 'Absent', 'Present'],
      read: ['Current', 'Resistance', 'Field through ring'], stamp: 'Stores, cannot supply',
      aria: 'A metal ring in a flask of liquid helium. Dots show a current circling the ring and arrows show its magnetic field.',
      claim: 'Cool a ring of lead in liquid helium and start a current in it. Below about seven kelvin lead has no electrical resistance at all, so the current has nothing to push against and should circle for ever.',
      why: 'This is the one figure on the sheet that nature very nearly allows. Currents like this have been watched for years with no measurable drop. But the helium has to be kept cold, which costs energy the whole time, and the current does no work. Draw power from it and it falls. Let the ring warm past its critical temperature and resistance returns, and the current is gone in a moment.' },
    { k: 1, m: 'villard', title: 'The hammer wheel', cap: 'Wheel of seven mallets, after Villard de Honnecourt, c. 1230', law: LAW1,
      read: ['Speed', 'Mallets on right', 'Mallets on left'], stamp: 'What falls must be lifted',
      aria: 'A wheel with seven hinged mallets on its rim. The mallets stand out on the right and hang down on the left.',
      claim: 'Seven mallets hang from the rim of a wheel on hinges. Going over the top each one flops forward and stands out from the rim, and on the way up it hangs limp. Villard de Honnecourt drew the wheel in his sketchbook around 1230. He chose an odd number so that four mallets would always be on the falling side against three on the rising side.',
      why: 'The mallets that stand out do have more leverage. The ones that hang close have less, but they are lifted through exactly the same height that the others fall. Follow one mallet all the way round and it ends where it began, having taken as much to raise as it gave coming down. The flopping only adds knocks and friction.' },
    { k: 1, m: 'taccola', title: 'The folding arms', cap: 'Wheel with jointed arms, after Taccola, c. 1430', law: LAW1,
      read: ['Speed', 'Arms held straight', 'Arms folded'], stamp: 'Straight or folded, it balances',
      aria: 'A hub with twelve jointed arms, each carrying a weight. Arms on the right are straight, arms on the left are folded at the elbow.',
      claim: 'Twelve jointed arms carry weights round a hub. On the way down each arm is held straight, so its weight rides far from the centre. On the way up the arm folds at the elbow and the weight tucks in close. The Sienese engineer Taccola drew a wheel of this kind around 1430.',
      why: 'What a weight gives on the way down depends only on how far it drops, and not on how far out it rides. Each weight climbs as high as it falls, so the two halves of the turn cancel. Bending and straightening the elbows costs a little extra.' },
    { k: 1, m: 'papin', title: 'The mercury bellows', cap: 'Anonymous French design, refuted by Denis Papin, 1685', law: LAW1,
      read: ['Cycles', 'Push from inside', 'Push of the air'], stamp: 'Air holds the bellows shut',
      aria: 'A pleated bellows on a pivot, joined by a pipe to a vessel of mercury, with a trough to carry the mercury back.',
      claim: 'A long airtight bellows hangs on a pivot and is joined by a pipe to a vessel of mercury. Mercury was meant to rise into the bellows and swell it until it overbalanced, tipped, and poured the mercury back into the vessel. A counterweight would then swing the empty bellows home to fill again. The scheme was printed in France, and Denis Papin took it apart in the Philosophical Transactions of 1685.',
      why: 'Papin did the sum. The mercury inside presses outward with the weight of a column about 25 inches high at best. The air outside presses inward on the boards with the weight of about 27 inches of mercury. The bellows, he wrote, must rather shut than open. Nothing rises and nothing tips.' },
    { k: 1, m: 'bessler', title: "Bessler's wheel", cap: 'Sealed wheel of Johann Bessler, called Orffyreus, 1717', law: LAW1,
      read: ['Speed', 'Loads lifted', 'Mechanism'], stamp: 'Never opened for inspection',
      aria: 'A large cloth-covered drum turning between two posts and winding up a box of bricks. A question mark covers its inside.',
      claim: 'Johann Bessler, who called himself Orffyreus, showed a hollow wheel covered in cloth that turned by itself and could lift a box of bricks. At Weissenstein castle in November 1717 it was locked in a sealed room, and it was turning when the seals were broken some 54 days later. Bessler asked a fortune for the secret and never let anyone look inside.',
      why: 'Nobody knows what was in it. A servant swore in 1727 that the wheel had been turned by hand from the next room, and her account has been doubted too. What can be said is that a wheel whose only power is falling weights cannot turn for 54 days, and that a machine nobody may examine has not been shown to work.' },
    { k: 1, m: 'bernoulli', title: 'The two-liquid fountain', cap: 'Filter and two liquids, attributed to Johann Bernoulli', law: LAW1,
      read: ['Mixture level', 'Level in the tube', 'Overflow'], stamp: 'The flow runs the other way',
      aria: 'A vessel of mixed liquid with a tube standing in it. A filter closes the foot of the tube and its top bends over the vessel.',
      claim: 'Mix a heavy liquid with a light one. Stand a tube in the mixture with a filter across its foot that lets only the light liquid through. A column of light liquid has to stand taller than the heavy mixture to press as hard, so it should climb the tube, spill over the top and fall back into the vessel for ever.',
      why: 'A filter that passes one liquid and holds back another is what chemists now call a semipermeable membrane, and flow through it runs the other way. The pure liquid in the tube is drawn out into the mixture, as fresh water is drawn into brine. The tube drains until that pull is balanced, well below the rim.' },
    { k: 1, m: 'capfount', title: 'The capillary fountain', cap: 'Hair-thin tube standing in water', law: LAW1,
      read: ['Rise in the tube', 'Drops', 'Wheel'], stamp: 'The drop will not let go',
      aria: 'A thin tube rises from a dish of water and bends over. Drops fall from its end onto a small paddle wheel.',
      claim: 'Water climbs a very thin tube without help, and climbs higher the thinner the tube. Bend the top of the tube over, and the water that has climbed should drip from the end onto a little wheel and run back to the dish, to climb again.',
      why: 'The water climbs because it clings to glass. At the open end the same clinging holds it back. A drop can only fall if it is heavier than the pull that raised the whole column, and it never is. The tube fills to the tip and stays full.' },
    { k: 1, m: 'siphon', title: 'The fat-legged siphon', cap: 'Siphon with one wide leg', law: LAW1,
      read: ['Narrow leg holds', 'Wide leg holds', 'Flow'], stamp: 'Width adds no push',
      aria: 'An upside-down U tube with one narrow leg and one wide leg, both standing in the same dish of water.',
      claim: 'A siphon runs because the water in its longer leg outweighs the water in the shorter one. So make one leg twenty times as wide. It now holds twenty times the water, and with both ends in the same dish it should drag water up the narrow leg and round for ever.',
      why: 'A siphon is driven by the difference in height between its two ends, and width has nothing to do with it. The pressure at the foot of a column depends on how tall the column is and not on how much it holds. Here both legs end at the same level, so nothing moves.' },
    { k: 1, m: 'chain', title: 'The lopsided chain', cap: 'Chain with a zigzag run', law: LAW1,
      read: ['Links on the zigzag', 'Links on the straight', 'Chain speed'], stamp: 'Only height counts',
      aria: 'An endless chain over two wheels. One side hangs straight and the other zigzags over four rollers.',
      claim: 'An endless chain hangs over two wheels. On one side it drops straight. On the other it is led back and forth over rollers, so that side holds half as many links again. More links weigh more, so the zigzag side should sink and haul the straight side up.',
      why: 'The extra links lie on slopes and rest part of their weight on the rollers. What pulls a chain down is only the height it spans, and both sides span the same height. Stevin proved as much with his wreath of spheres.' },
    { k: 1, m: 'ballscrew', title: 'The ball mill', cap: 'Wheel fed by its own screw', law: LAW1,
      read: ['Wheel', 'Each ball gives', 'Each lift costs'], stamp: 'Lifting costs what falling gives',
      aria: 'Balls ride down one side of a wheel, roll along a chute into an Archimedes screw, and are carried back to the top.',
      claim: 'Heavy balls ride down one side of a wheel and turn it. At the bottom they roll off into an Archimedes screw, which the wheel itself drives, and the screw carries them back to the top. The balls on the wheel are many and the screw looks easy to turn.',
      why: 'A ball gives the wheel its weight times the height it falls. The screw must give every ball that same weight times that same height to put it back. The screw spreads the effort over many turns, which makes each turn feel light, but the total is identical. Friction in the screw is the loss that stops it.' },
    { k: 1, m: 'bfloat', title: 'The opening floats', cap: 'Wheel of bellows floats under water', law: LAW1,
      read: ['Speed', 'Extra lift per float', 'Cost of opening it'], stamp: 'Opening costs the lift',
      aria: 'A wheel under water carrying eight floats. The floats on the left are swollen and those on the right are small.',
      claim: 'A wheel turns under water with a bellows float on each arm. A small weight pulls each bellows open on one side of the wheel and squeezes it shut on the other. The open floats push aside more water and are buoyed up harder, so their side should always rise.',
      why: 'A float can only swell by pushing water out of its way, and the water pushes back. It pushes hardest at the bottom of the tank, which is where the float has to open. The work of opening it there is exactly the extra lift it earns on the way up.' },
    { k: 1, m: 'shield', title: 'The shielded magnet wheel', cap: 'Rotor of magnets with a shield', law: LAW1,
      read: ['Speed', 'Gained on approach', 'Lost on leaving'], stamp: 'No shield for magnetism',
      aria: 'A wheel with eight magnets on its rim beside a fixed magnet. A curved plate covers part of the rim below the fixed magnet.',
      claim: 'Magnets ride on the rim of a wheel, and a fixed magnet beside it pulls each one as it comes near. The trouble is that it pulls just as hard when the magnet tries to leave. So put a shield in the way on the far side, and the wheel should be drawn round and round. Most magnet motors offered today are versions of this.',
      why: 'Nothing blocks magnetism the way a wall blocks wind. An iron plate only gathers the field and bends it somewhere else, and then the plate itself tugs on the rotor. Add up the pushes and pulls over one full turn and they come to nothing. The wheel rocks and settles with one magnet facing the fixed one.' },
    { k: 1, m: 'gears', title: 'The self-multiplying gears', cap: 'Gear train closed on itself', law: LAW1,
      read: ['Small gear', 'Large gear', 'Twist gained'], stamp: 'Geared against itself',
      aria: 'A small gear meshed with a large gear, with a crossed belt joining pulleys on the two shafts.',
      claim: 'A small gear driving a large one triples the twisting force. So take that tripled force from the large gear by a belt and feed it back to the small gear, which triples it again. Each trip round the loop should make the machine stronger.',
      why: 'Gears trade speed for force. The large gear twists three times as hard and turns three times as slowly, so nothing is gained. Worse, the belt asks both shafts to turn at one speed while the teeth insist on three to one. The loop cannot satisfy both, so it locks solid.' },
    { k: 1, m: 'waterfuel', title: 'Water as fuel', cap: 'Water split and burned in a ring', law: LAW1,
      read: ['Cell draws', 'Dynamo returns', 'Lamp gets'], stamp: 'Water is already ash',
      aria: 'A cell splitting water into gas, a pipe carrying the gas to an engine and dynamo, wires back to the cell and a pipe returning water.',
      claim: 'Electricity splits water into hydrogen and oxygen. Hydrogen burns fiercely and its only exhaust is water. So burn the hydrogen in an engine, drive a dynamo, send the current back to the cell and return the exhaust to the tank. The car that runs on water turns up in the news every few years.',
      why: 'Burning hydrogen gives back exactly the energy that splitting the water took, and not a joule more. Water is what hydrogen becomes when it has burned, so it is ash and not fuel. A real cell loses some of the energy as heat, and an engine with a dynamo turns about a quarter of the rest into current.' },

    { k: 2, m: 'loschmidt', title: "Loschmidt's column", cap: 'Gas column under gravity, after Josef Loschmidt, 1876', law: LAW2,
      read: ['Bottom', 'Top', 'Engine'], stamp: 'Thinner at the top, not colder',
      aria: 'A tall column of gas molecules, denser at the bottom, with an engine wheel connected to its top and bottom.',
      claim: 'A molecule climbing against gravity slows down, as a thrown ball does. So in a tall column of gas the molecules at the top should be slower, which means colder, than those at the bottom. Josef Loschmidt argued this in 1876. If he were right, an engine joined to the top and the bottom could run on the difference for ever.',
      why: 'Maxwell and Boltzmann showed where the argument slips. Every molecule does slow as it rises, but the slowest never reach the top at all. Those that arrive are the ones that set out fast, and they arrive with the same spread of speeds as the gas below. The top is thinner, not colder. With one temperature throughout, the engine has nothing to run on.' },
    { k: 2, m: 'mirror', title: 'The one-way mirror', cap: 'Two warm bodies and a one-way mirror', law: LAW2,
      read: ['Body A', 'Body B', 'Mirror'], stamp: 'Heat rays pass both ways',
      aria: 'Two blocks facing each other with a mirror between them. Dots of radiation cross from left to right and are turned back from right to left.',
      claim: 'Every warm body sheds heat rays. Put two bodies at the same temperature face to face, with a sheet between them that lets rays pass from left to right and turns back any going the other way. The body on the right is now fed by both and must grow hotter, the one on the left colder, and an engine can run between them.',
      why: 'No passive sheet does this. A surface that lets heat rays through from one side lets the same rays through from the other, and a mirror that reflects on one face reflects on the other. The windows called one-way mirrors only seem to work because one room is bright and the other dark. With equal traffic both ways the two bodies stay at one temperature.' },
    { k: 2, m: 'trapdoor', title: 'The trapdoor', cap: 'Spring flap, after Smoluchowski, 1912', law: LAW2,
      read: ['Molecules on left', 'Molecules on right', 'Flap'], stamp: 'The flap flutters too',
      aria: 'A box of gas molecules divided by a wall with a hinged flap. A pipe with a turbine joins the two halves underneath.',
      claim: "Replace Maxwell's demon with something that needs no brain: a feather-light flap on a weak spring, hinged so that it opens to the right only. A molecule striking it from the left pushes through. One striking from the right slams it shut. Gas should pile up on the right, and the pressure can drive a turbine on its way back.",
      why: 'Smoluchowski saw the flaw in 1912. A flap light enough to be pushed open by one molecule is light enough to be shaken by its own warmth. It flutters open and shut at random, and whenever it happens to be open, molecules pass both ways. The numbers on the two sides stay equal and the turbine stands still.' },
    { k: 2, m: 'szilard', title: "Szilard's engine", cap: 'One-molecule engine, after Leo Szilard, 1929', law: LAW2,
      read: ['Cycles', 'Work gained per cycle', 'Cost of wiping record'], stamp: 'Forgetting costs as much',
      aria: 'A single molecule in a box. A partition drops into the middle, slides to one side as a piston and lifts a weight, while a panel records left or right.',
      claim: 'Shrink the gas to a single molecule. Slide a partition into the middle of its box and note which side the molecule is on. Now let the molecule push the partition toward the empty side like a piston, lifting a small weight as it goes. Pull the partition out and start again. Each cycle turns a little heat into work at one temperature. Leo Szilard published the idea in 1929.',
      why: 'The engine only works if someone records which side the molecule was on, one bit each cycle. To run for ever the record must be wiped and used again, and wiping one bit gives off at least as much heat as the stroke turned into work. Here the weight sinks back while the record is erased. This small box is where the link between information and heat was first worked out.' },
    { k: 2, m: 'thermoloop', title: 'The two-metal ring', cap: 'Ring of copper and bismuth', law: LAW2,
      read: ['Top junction', 'Bottom junction', 'Current'], stamp: 'The two junctions cancel',
      aria: 'A ring made half of copper and half of bismuth, with a compass needle in the middle.',
      claim: 'Wherever two different metals touch, a small voltage appears. Join a strip of copper and a strip of bismuth at both ends to make a ring, and the two junction voltages should drive a current round it for nothing. A compass needle inside the ring would show it.',
      why: 'Going round the ring you cross one junction from copper to bismuth and the other from bismuth to copper. At one temperature the two voltages are equal and opposite, and no current flows. Thomas Seebeck found in 1821 that the needle moves only when one junction is heated. That is a thermocouple, and it is a heat engine like any other.' },
    { k: 2, m: 'radiometer', title: 'The radiometer in the dark', cap: 'Light mill, after William Crookes, 1873', law: LAW2,
      read: ['Vanes', 'Black faces', 'Bright faces'], stamp: 'Needs something hotter',
      aria: 'A glass bulb holding four vanes on a pivot, each black on one face and bright on the other, with heat rays arriving from all sides.',
      claim: "Crookes's radiometer is a real thing. Four vanes, black on one face and bright on the other, spin inside a glass bulb when light falls on them. Every object in a room gives off heat rays, so the vanes should keep spinning in a closed, dark room, driven by the warmth of the walls alone.",
      why: 'The vanes turn when their black faces are warmer than their bright ones, and that takes light from something hotter than the bulb, such as the sun or a lamp. In a room where everything is at one temperature each face takes in exactly as much as it gives out. Both faces stay equally warm and the mill hangs still.' },
    { k: 2, m: 'heatpump', title: 'The heat pump loop', cap: 'Heat pump driving its own engine', law: LAW2,
      read: ['Pump takes', 'Heat delivered', 'Engine returns'], stamp: 'Engine returns less than it took',
      aria: 'A heat pump and a heat engine between a warm bar and a cold bar, with arrows for heat and a work arrow from the engine to the pump.',
      claim: 'A heat pump is a real machine that delivers three or four units of heat for every unit of work it is given. So let it warm a room, run a heat engine on that warmth, and use the engine to drive the pump. One unit in, three out. There should be plenty to spare.',
      why: 'The pump does not make three units of heat. It moves them uphill from a colder place, and that is cheap only when the hill is low. An engine run across the same low hill is feeble for the same reason. For ideal machines the two effects cancel exactly and the engine returns the one unit the pump used. Real machines return less.' },

    { k: 3, m: 'bowl', title: 'The ball in the bowl', cap: 'Ball rolling in a frictionless bowl', law: ['Rolling resistance', 'Removed', 'Present'],
      read: ['Crossings', 'Height reached', 'Energy left'], stamp: 'Rolling is never free',
      aria: 'A ball rolling to and fro in a shallow bowl, with a dashed line at the height it was released from.',
      claim: 'Let a ball go from the rim of a smooth bowl. It rolls down, up the far side to the height it started from, and back. Galileo used this to argue that motion needs nothing to keep it going. With a perfect ball and a perfect bowl it would never stop.',
      why: 'A real ball flattens slightly where it touches, and the bowl dents slightly beneath it. Both spring back a moment late, which turns a little motion into heat on every pass. The air takes some more. Each climb stops short of the last and the ball settles at the bottom.' },
    { k: 3, m: 'spring', title: 'The weight on a spring', cap: 'Weight on a perfect spring', law: ['Losses inside the spring', 'Removed', 'Present'],
      read: ['Bounces', 'Travel', 'Energy left'], stamp: 'Steel warms as it flexes',
      aria: 'A weight bobbing up and down on a coil spring beside a ruler.',
      claim: 'Hang a weight on a spring, pull it down and let go. The spring stores the energy on the way down and hands it back on the way up. If the steel gave back everything it took, the weight would bob for ever.',
      why: 'No spring returns all it is given. Each time the steel flexes, its crystals slip against one another by a hair and warm up. The air drags on the weight and the support shakes a little. Every bounce is a few percent smaller than the last.' },
    { k: 3, m: 'top', title: 'The spinning top', cap: 'Top on a perfect point', law: ['Friction at the point', 'Removed', 'Present'],
      read: ['Spin', 'Lean', 'State'], stamp: 'The point always rubs',
      aria: 'A spinning top standing on its point.',
      claim: 'A spinning top stands up because it spins. On a point with no friction, in a room with no air, nothing would slow the spin, and a top that never slows never falls.',
      why: 'The point rubs on the floor and the air drags on the body. As the spin fades the top leans, and the lean swings round faster and wider. When it is too slow to hold itself up it falls over.' },
    { k: 3, m: 'fork', title: 'The tuning fork', cap: 'Tuning fork in a vacuum', law: ['Air and inner friction', 'Removed', 'Present'],
      read: ['Note', 'Strength', 'Sound given off'], stamp: 'A note you hear is a loss',
      aria: 'A tuning fork with trembling prongs, under a glass jar.',
      claim: 'Strike a tuning fork inside a jar with the air pumped out. With no air to carry sound away, and steel that springs back perfectly, the prongs should go on trembling for ever in silence.',
      why: 'Let the air back in and you can hear the fork, which means it is giving energy to the room with every swing. Even in a vacuum the steel warms a little as it bends, and the stem shakes whatever holds it. A good fork rings for a minute or so.' },
    { k: 3, m: 'orbit', title: 'The satellite', cap: 'Satellite in low orbit', law: ['Traces of air', 'Removed', 'Present'],
      read: ['Orbits', 'Height', 'Drag'], stamp: 'Thin air is still air',
      aria: 'A small satellite circling the Earth.',
      claim: 'Throw something fast enough and it falls round the Earth without ever landing. Above the air nothing slows it, so a satellite should circle for ever.',
      why: 'Low orbits are not quite above the air. The International Space Station ploughs through enough stray gas to sink about two kilometres a month, and has to be boosted. Higher up the drag fades but never quite vanishes, and tides slowly rob even moons of their motion. An orbit lasts a long time, and it is no engine. Take work from it and it decays.' },
    { k: 3, m: 'light', title: 'The trapped flash', cap: 'Flash of light between two mirrors', law: ['Losses at the mirrors', 'Removed', 'Present'],
      read: ['Bounces', 'Brightness', 'Lost at each bounce'], stamp: 'No mirror returns it all',
      aria: 'A flash of light bouncing to and fro between two facing mirrors.',
      claim: 'Send a flash of light in between two mirrors that face each other. If the mirrors returned every bit of it, the flash would bounce between them for ever.',
      why: 'Every mirror absorbs or leaks a little. The best ever made still lose several parts in a million at each bounce, and light crosses a gap of one metre three hundred million times a second. The flash is gone in about a thousandth of a second. The mirrors drawn here are far worse, so that you can watch it fade.' },
    { k: 3, m: 'lc', title: 'The ringing circuit', cap: 'Coil and capacitor with no resistance', law: ['Resistance and radiation', 'Removed', 'Present'],
      read: ['Swings', 'Voltage', 'Lost in each swing'], stamp: 'Wire resists, loop radiates',
      aria: 'A loop of wire joining a capacitor and a coil, with a trace of the voltage swinging up and down.',
      claim: 'Charge a capacitor and connect it to a coil. The charge rushes through the coil and builds a magnetic field, and the field drives the charge on to the opposite plate. Then it all runs back. With wire of no resistance the charge would slosh to and fro for ever.',
      why: 'Ordinary wire turns some of the current into heat on every pass. A circuit like this is also a small radio transmitter, and sends a little energy off as waves. The swings die away in a fraction of a second, which is why every oscillator in every radio and clock needs a power supply.' },
    { k: 3, m: 'superfluid', title: 'The superfluid ring', cap: 'Superfluid helium in a ring', law: ['Viscosity', 'Absent', 'Present'],
      read: ['Flow', 'Stickiness', 'Laps'], stamp: 'Flows, but gives nothing',
      aria: 'A ring-shaped channel of liquid seen from above, with marks showing the liquid flowing round.',
      claim: 'Below about two kelvin liquid helium turns into a superfluid, a liquid with no stickiness at all. Set it flowing round a ring-shaped channel and there is nothing to slow it. It should circle for ever.',
      why: 'Like the current in a superconductor, this is real, and the flow has been seen to go on for as long as anyone has watched. But it needs a refrigerator running the whole time, and it does no work. Warm the helium past 2.17 kelvin and it becomes an ordinary liquid, whose stickiness stops the flow in seconds.' },

    { k: 4, m: 'redheffer', title: "Redheffer's machine", cap: 'Charles Redheffer, Philadelphia, 1812', tag: 'Impostor · a fraud', law: ['The floor above', 'Boarded over', 'Opened'],
      read: ['Machine', 'Weights on ramps', 'Man upstairs'], stamp: 'A man with a crank',
      aria: 'A machine with a horizontal gear wheel and weights on ramps, below a boarded ceiling.',
      claim: 'Charles Redheffer charged the people of Philadelphia to see a machine that ran by itself. Weights in two boxes pressed on ramps set at 45 degrees and, he said, pushed a horizontal wheel round without end. He asked the state for money to build a bigger one.',
      why: 'The engineer sent to inspect it noticed that the teeth of the gears were worn on the wrong side. The small gear that the machine was supposed to drive was in fact driving the machine. When Redheffer took the show to New York, Robert Fulton pulled away some boards and followed a catgut cord to an upper room, where an old man sat turning a crank.' },
    { k: 4, m: 'keely', title: 'The Keely motor', cap: 'John Keely, Philadelphia, 1872 to 1898', tag: 'Impostor · a fraud', law: ['The floorboards', 'In place', 'Lifted'],
      read: ['Engine', 'Gauge', 'Air from below'], stamp: 'Compressed air in the cellar',
      aria: 'A workshop with a spinning engine, a pressure gauge and two tuning forks, standing on a floor whose underside is hidden.',
      claim: 'John Keely announced in 1872 that he could release the force locked in a few drops of water by making it vibrate in sympathy with a tuning fork. For twenty-six years he gave demonstrations in his workshop, where gauges leapt and engines spun, and investors paid him to perfect the machine. It was always nearly ready.',
      why: 'After Keely died in 1898 the floor of the workshop was taken up. In a pit beneath it lay a steel sphere weighing about three tons, a reservoir for compressed air. Hidden pipes ran from it through the floors and walls, and a thin tube that Keely had always called a solid wire led to each machine. He seems to have worked the valves with his foot.' },
    { k: 4, m: 'cox', title: "Cox's timepiece", cap: 'James Cox and John Joseph Merlin, 1760s', tag: 'Impostor · fed by its surroundings', law: ['Changes in air pressure', 'Supplied', 'Removed'],
      read: ['Air pressure', 'Spring wound', 'Clock'], stamp: 'Wound by the weather',
      aria: 'A clock in a cabinet linked by a chain to a large mercury barometer.',
      claim: 'A clock that nobody ever winds. James Cox, a London jeweller, built it in the 1760s with the inventor John Joseph Merlin and presented it as a perpetual motion. It did run by itself for years.',
      why: 'Inside the case is a barometer holding about 68 kilograms of mercury. When the weather changes, the air presses more or less on the mercury, which shifts its weight between the tube and the cistern. Whichever way it moves, a ratchet turns the movement into winding. The clock runs on the weather, and where the pressure never changed it would run down and stop.' },
    { k: 4, m: 'watch', title: 'The self-winding watch', cap: 'Automatic watch, after Perrelet, c. 1777', tag: 'Impostor · fed by its surroundings', law: ["The wearer's wrist", 'Moving', 'Still'],
      read: ['Rotor swings', 'Reserve', 'Watch'], stamp: 'Wound by your wrist',
      aria: 'The back of a wristwatch, showing a half-disc rotor swinging over the gears and balance wheel.',
      claim: 'A watch that winds itself. Abraham-Louis Perrelet made the first in Switzerland around 1777, and millions are worn today. It has no battery and no key, and it will run for years.',
      why: 'Behind the dial a half-disc of heavy metal swings on a pivot whenever the watch is moved. A ratchet turns each swing, in either direction, into a little winding of the mainspring. The energy comes from the wearer. Leave the watch on a table and it runs down in about two days.' },
    { k: 4, m: 'oxford', title: 'The Oxford Electric Bell', cap: 'Clarendon Laboratory, Oxford, ringing since 1840', tag: 'Impostor · fed by its surroundings', law: ['Charge in the piles', 'Remaining', 'Spent'],
      read: ['Rings so far', 'Swings', 'Charge'], stamp: 'A very slow battery',
      aria: 'Two tall dry piles, each with a bell beneath it, and a small ball swinging between the bells under a glass jar.',
      claim: 'In a hallway in Oxford a small metal ball has been swinging between two bells since 1840, about twice a second. It has rung something like ten billion times. Nobody has wound it, and nobody has changed the batteries.',
      why: 'It runs on two dry piles, early batteries made of thousands of stacked discs sealed in sulphur. Each time the ball touches a bell it carries a tiny charge across to the other, and the current is so small that the piles have lasted nearly two centuries. They are running down all the same. One day the ball will hang still.' },
    { k: 4, m: 'beverly', title: 'The Beverly Clock', cap: 'Arthur Beverly, Dunedin, 1864', tag: 'Impostor · fed by its surroundings', law: ['Daily swings in temperature', 'Supplied', 'Shut out'],
      read: ['Air in the box', 'Weight wound up', 'Clock'], stamp: 'Wound by day and night',
      aria: 'A clock face, a driving weight on a chain, and a sealed box of air with a diaphragm, under a sky where the sun and moon cross in turn.',
      claim: 'A clock at the University of Otago in New Zealand has been going since 1864 and has never been wound by hand. Arthur Beverly built it to need nobody.',
      why: 'Behind the clock is an airtight box holding a cubic foot of air. As the room warms by day and cools by night, the air swells and shrinks and pushes a diaphragm in and out. Each push lifts the driving weight a little. The clock has stopped a few times, for cleaning, for repairs, and when the temperature held too steady for too long.' },
    { k: 4, m: 'atmos', title: 'The Atmos clock', cap: 'Jean-Léon Reutter, 1928', tag: 'Impostor · fed by its surroundings', law: ['Changes in room temperature', 'Supplied', 'Removed'],
      read: ['Room', 'Spring wound', 'Clock'], stamp: 'Wound by the room',
      aria: 'A clock in a glass case with a slowly twisting pendulum, a gas capsule that swells and shrinks, and a thermometer beside it.',
      claim: 'A mantel clock, still made by Jaeger-LeCoultre, that runs for decades with no winding, no battery and no cord. Jean-Léon Reutter designed it in 1928. It is sometimes sold as the nearest thing to perpetual motion.',
      why: 'A sealed capsule in the back holds a gas that swells when the room warms and shrinks when it cools. The capsule breathes like a bellows and winds the mainspring. A change of one degree is enough for about two days. The clock helps by needing almost nothing, since its pendulum twists to and fro only once a minute.' },
    { k: 4, m: 'bird', title: 'The drinking bird', cap: 'Glass toy, patented by Miles V. Sullivan, 1946', tag: 'Impostor · fed by its surroundings', law: ['Dry air around it', 'Supplied', 'Sealed off'],
      read: ['Dips', 'Head, wet', 'Body'], stamp: 'A heat engine in disguise',
      aria: 'A glass bird on a pivot tipping forward to dip its beak in a glass of water.',
      claim: 'A glass bird rocks on a pivot beside a glass of water. Every few seconds it tips forward, dips its beak, swings back and starts again. It has no spring and no battery, and it will keep this up for as long as there is water in the glass.',
      why: 'The head is covered in wet felt. As the water evaporates it cools the head, and the vapour inside the head shrinks. The warmer vapour in the body then pushes liquid up the neck until the bird tips over, and the dip wets the felt again. The bird runs on the difference between its cool head and the warm room. Put it under a jar, where the air soon turns damp and evaporation stops, and it stands still.' }
];
const ORDER = [
  'wheel', 'villard', 'taccola', 'windmill', 'stevin', 'fludd', 'wilkins', 'boyle', 'papin', 'bessler', 'bernoulli', 'congreve',
  'capfount', 'siphon', 'chain', 'ballscrew', 'floats', 'bfloat', 'drum', 'shield', 'gears', 'motor', 'waterfuel', 'cart',
  'demon', 'loschmidt', 'zero', 'ship', 'mirror', 'trapdoor', 'ratchet', 'szilard', 'diode', 'thermoloop', 'radiometer', 'heatpump',
  'pend', 'bowl', 'spring', 'cradle', 'top', 'fork', 'fly', 'orbit', 'light', 'lc', 'ring', 'superfluid',
  'redheffer', 'keely', 'cox', 'watch', 'oxford', 'beverly', 'atmos', 'bird'];
const by = Object.fromEntries(ALL.map(f => [f.m, f]));
module.exports = ORDER.map(s => { if (!by[s]) throw new Error('no text for ' + s); return by[s]; });
if (ALL.length !== ORDER.length) throw new Error('count mismatch ' + ALL.length + ' ' + ORDER.length);
